mapper.select:
select a.*,b.PRODUCT_TYPE_CODE,b.VULCANIZING_MACHINE_CODE from T_MDM_VULCANIZING_MACH_STATUS a
left join t_mdm_vulcanizing_machine b
on a.vulcanizing_machine_id = b.id
where ifnull(a.is_delete, 0) = 0

    and a.year = #{year}


    and a.month = #{month}

and a.factory_code = #{factoryCode}
and a.vulcanizing_machine_id = #{vulcanizingMachineId}
and a.status = #{status}
${params.dataScope}
order by a.factory_code,b.product_type_code,
REGEXP_REPLACE(b.VULCANIZING_MACHINE_CODE,'[^0-9]',''),
ifnull(REGEXP_REPLACE(b.VULCANIZING_MACHINE_CODE,'[0-9]',''),'0') asc

select count(1) from T_MDM_VULCANIZING_MACH_STATUS a
where a.is_delete = '0'
and a.year = #{year}
and a.month = #{month}
and a.factory_code = #{factoryCode}
and a.vulcanizing_machine_id = #{vulcanizingMachineId}
and a.id != #{id}

SELECT FACTORY_CODE, #{generateToYear,jdbcType=DECIMAL} year, #{generateToMonth,jdbcType=DECIMAL} month, id AS VULCANIZING_MACHINE_ID, 1 status, remark, 0 as IS_DELETE, now() as CREATE_TIME FROM t_mdm_vulcanizing_machine WHERE IS_DELETE = 0
and factory_code = #{factoryCode,jdbcType=VARCHAR}
${params.dataScope}

mapper.update:
update T_MDM_VULCANIZING_MACH_STATUS
set status = #{status}
where ID in

    #{item,jdbcType=DECIMAL}

mapper.delete:
update T_MDM_VULCANIZING_MACH_STATUS
set IS_DELETE = 1
where
YEAR = #{copyToYear}
and MONTH = #{copyToMonth}

    and factory_code = #{factoryCode,jdbcType=VARCHAR}

${params.dataScope}
